use crate::{is_name_char, is_name_start, is_xml_char, is_xml_whitespace, utf8_next};

pub const MAX_INPUT_BYTES: usize = 16 * 1024 * 1024;
pub const MAX_LARGE_INPUT_BYTES: usize = 1024 * 1024 * 1024;
pub const MAX_DEPTH: usize = 256;
pub const MAX_NODES: usize = 1_000_000;
pub const MAX_ATTRIBUTES_PER_ELEMENT: usize = 4096;
pub const MAX_TOTAL_ATTRIBUTES: usize = 1_000_000;
pub const MAX_TEXT_RUN_BYTES: usize = 4 * 1024 * 1024;
pub const MAX_TOKEN_NAME_BYTES: usize = 4096;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum TokenKind { Declaration = 1, ProcessingInstruction, Comment, StartElement, EndElement,
    EmptyElement, Attribute, Text, Cdata, Doctype }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum XmlError { None, InvalidArgument, InputLimit, InvalidUtf8, InvalidCharacter,
    UnsupportedEncoding, InvalidName, MalformedSyntax, DuplicateAttribute, MismatchedTag,
    DepthLimit, NodeLimit, AttributeLimit, TextLimit, OutputExhausted, UnsupportedDtd,
    MultipleRoots, IncompleteDocument }

impl XmlError {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::None => "none", Self::InvalidArgument => "invalid_argument", Self::InputLimit => "input_limit",
            Self::InvalidUtf8 => "invalid_utf8", Self::InvalidCharacter => "invalid_character",
            Self::UnsupportedEncoding => "unsupported_encoding", Self::InvalidName => "invalid_name",
            Self::MalformedSyntax => "malformed_syntax", Self::DuplicateAttribute => "duplicate_attribute",
            Self::MismatchedTag => "mismatched_tag", Self::DepthLimit => "depth_limit", Self::NodeLimit => "node_limit",
            Self::AttributeLimit => "attribute_limit", Self::TextLimit => "text_limit", Self::OutputExhausted => "output_exhausted",
            Self::UnsupportedDtd => "unsupported_dtd", Self::MultipleRoots => "multiple_roots", Self::IncompleteDocument => "incomplete_document",
        }
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct XmlSpan { pub offset: usize, pub length: usize }
impl XmlSpan {
    pub fn end(self) -> Option<usize> { self.offset.checked_add(self.length) }
    pub fn slice<'a>(self, source: &'a [u8]) -> Option<&'a [u8]> { source.get(self.offset..self.end()?) }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct XmlToken { pub kind: TokenKind, pub source: XmlSpan, pub name: XmlSpan, pub value: XmlSpan,
    pub prefix: XmlSpan, pub local_name: XmlSpan, pub depth: usize }
impl Default for TokenKind { fn default() -> Self { Self::Declaration } }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct XmlLimits { pub input_bytes: usize, pub nesting_depth: usize, pub nodes: usize,
    pub attributes_per_element: usize, pub total_attributes: usize, pub text_run_bytes: usize }
impl Default for XmlLimits { fn default() -> Self { Self { input_bytes: MAX_INPUT_BYTES, nesting_depth: MAX_DEPTH,
    nodes: MAX_NODES, attributes_per_element: MAX_ATTRIBUTES_PER_ELEMENT, total_attributes: MAX_TOTAL_ATTRIBUTES,
    text_run_bytes: MAX_TEXT_RUN_BYTES } } }

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct XmlDiagnostic { pub category: XmlError, pub offset: usize }
impl Default for XmlError { fn default() -> Self { Self::None } }
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct XmlResult { pub token_count: usize, pub element_count: usize, pub attribute_count: usize,
    pub node_count: usize, pub diagnostic: XmlDiagnostic }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Fault(pub(crate) XmlError, pub(crate) usize);

struct Parser<'a> { src: &'a [u8], pos: usize, depth: usize, roots: usize, attrs: usize,
    limits: XmlLimits, tokens: Vec<XmlToken>, result: XmlResult, open_names: Vec<XmlSpan>, token_capacity: usize }
impl<'a> Parser<'a> {
    fn fault<T>(&self, e: XmlError, at: usize) -> Result<T, Fault> { Err(Fault(e, at.min(self.src.len()))) }
    fn emit(&mut self, token: XmlToken, at: usize) -> Result<(), Fault> {
        if self.tokens.len() >= self.token_capacity { return self.fault(XmlError::OutputExhausted, at); }
        if self.tokens.try_reserve(1).is_err() { return self.fault(XmlError::OutputExhausted, at); }
        self.tokens.push(token); self.result.token_count += 1; Ok(())
    }
    fn node(&mut self, at: usize) -> Result<(), Fault> {
        let n = self.result.node_count.checked_add(1).ok_or(Fault(XmlError::NodeLimit, at))?;
        if n > self.limits.nodes { return self.fault(XmlError::NodeLimit, at); } self.result.node_count = n; Ok(())
    }
    fn starts(&self, b: usize, lit: &[u8]) -> bool { self.src.get(b..b.saturating_add(lit.len())) == Some(lit) }
    fn ws(&self, p: &mut usize) { while self.src.get(*p).is_some_and(|b| is_xml_whitespace(*b)) { *p += 1; } }
    fn name(&self, p: &mut usize, qname: bool) -> Result<(XmlSpan, XmlSpan, XmlSpan), Fault> {
        let start = *p; let Some((cp, mut q)) = utf8_next(self.src, *p) else { return self.fault(XmlError::InvalidName, start) };
        if !is_name_start(cp) { return self.fault(XmlError::InvalidName, start); }
        let mut colon = None;
        while q < self.src.len() {
            let before = q; let Some((cp, next)) = utf8_next(self.src, q) else { return self.fault(XmlError::InvalidUtf8, q) };
            if !is_name_char(cp) { break; }
            if cp == 0x3a { if qname && colon.is_some() { return self.fault(XmlError::InvalidName, colon.unwrap_or(before)); } if colon.is_none() { colon = Some(before); } }
            q = next;
        }
        if q - start > MAX_TOKEN_NAME_BYTES { return self.fault(XmlError::MalformedSyntax, start); }
        if qname && (self.src.get(start) == Some(&b':') || self.src.get(q.saturating_sub(1)) == Some(&b':')) {
            return self.fault(XmlError::InvalidName, start);
        }
        let name = XmlSpan { offset: start, length: q - start };
        let (prefix, local) = match colon {
            Some(c) => (XmlSpan { offset: start, length: c - start }, XmlSpan { offset: c + 1, length: q - c - 1 }),
            None => (XmlSpan { offset: start, length: 0 }, name),
        };
        if qname && local.length > 0 {
            let Some((local_first, _)) = utf8_next(self.src, local.offset) else { return self.fault(XmlError::InvalidUtf8, local.offset) };
            if !is_name_start(local_first) { return self.fault(XmlError::InvalidName, local.offset); }
        }
        *p = q; Ok((name, prefix, local))
    }
    fn reference(&self, p: &mut usize) -> Result<(), Fault> {
        let at = *p; let mut q = at + 1;
        if q >= self.src.len() { return self.fault(XmlError::MalformedSyntax, at); }
        if self.src[q] == b'#' {
            q += 1; let hex = self.src.get(q) == Some(&b'x'); if hex { q += 1; }
            let begin = q; let mut n: u32 = 0;
            while let Some(&c) = self.src.get(q) {
                let digit = match c { b'0'..=b'9' => Some((c - b'0') as u32), b'a'..=b'f' if hex => Some((c-b'a'+10) as u32), b'A'..=b'F' if hex => Some((c-b'A'+10) as u32), _ => None };
                let Some(d) = digit else { break };
                n = n.checked_mul(if hex {16} else {10}).and_then(|v| v.checked_add(d)).filter(|v| *v <= 0x10ffff)
                    .ok_or(Fault(XmlError::MalformedSyntax, at))?; q += 1;
            }
            if q == begin || self.src.get(q) != Some(&b';') { return self.fault(XmlError::MalformedSyntax, at); }
            if !is_xml_char(n) { return self.fault(XmlError::InvalidCharacter, at); }
        } else {
            let begin = q; let (_, _, _) = self.name(&mut q, false).map_err(|_| Fault(XmlError::MalformedSyntax, at))?;
            if self.src.get(q) != Some(&b';') || !matches!(&self.src[begin..q], b"lt"|b"gt"|b"amp"|b"apos"|b"quot") { return self.fault(XmlError::MalformedSyntax, at); }
        }
        *p = q + 1; Ok(())
    }
    fn tag(&mut self, closing: bool) -> Result<(), Fault> {
        let start = self.pos; let mut p = start + if closing { 2 } else { 1 };
        let (name, prefix, local) = self.name(&mut p, true)?;
        if closing {
            self.ws(&mut p); if self.src.get(p) != Some(&b'>') { return self.fault(XmlError::MalformedSyntax, p); }
            if self.depth == 0 { return self.fault(XmlError::MismatchedTag, start); }
            // Stack is maintained separately by matching starts in depth order.
            let expected = self.open_names.last().copied().unwrap_or_default();
            if expected.slice(self.src) != name.slice(self.src) { return self.fault(XmlError::MismatchedTag, start); }
            self.emit(XmlToken { kind: TokenKind::EndElement, source: XmlSpan { offset: start, length: p + 1 - start }, name, prefix, local_name: local, depth: self.depth - 1, ..XmlToken::default() }, start)?;
            self.depth -= 1; self.open_names.pop(); self.pos = p + 1; return Ok(());
        }
        if self.depth == 0 { if self.roots != 0 { return self.fault(XmlError::MultipleRoots, start); } self.roots += 1; }
        if self.depth >= self.limits.nesting_depth || self.depth >= MAX_DEPTH { return self.fault(XmlError::DepthLimit, start); }
        self.node(start)?;
        let token_index = self.tokens.len(); self.emit(XmlToken { kind: TokenKind::StartElement, source: XmlSpan { offset: start, length: p - start }, name, prefix, local_name: local, depth: self.depth, ..XmlToken::default() }, start)?;
        let mut local_attrs = 0;
        loop {
            let before = p; self.ws(&mut p); let separated = p != before;
            match self.src.get(p).copied() {
                Some(b'>') => { self.tokens[token_index].source.length = p + 1 - start; if self.open_names.try_reserve(1).is_err() { return self.fault(XmlError::OutputExhausted, start); } self.open_names.push(name); self.depth += 1; self.pos = p + 1; return Ok(()); }
                Some(b'/') if self.src.get(p + 1) == Some(&b'>') => { self.tokens[token_index].kind = TokenKind::EmptyElement; self.tokens[token_index].source.length = p + 2 - start; self.pos = p + 2; return Ok(()); }
                None => return self.fault(XmlError::MalformedSyntax, start),
                _ if !separated => return self.fault(XmlError::MalformedSyntax, p),
                _ => {}
            }
            if local_attrs >= self.limits.attributes_per_element || self.attrs >= self.limits.total_attributes { return self.fault(XmlError::AttributeLimit, p); }
            let attr_start = p; let (an, ap, al) = self.name(&mut p, true)?;
            if self.tokens[token_index + 1..].iter().any(|t| t.kind == TokenKind::Attribute && an.slice(self.src) == t.name.slice(self.src)) { return self.fault(XmlError::DuplicateAttribute, attr_start); }
            self.ws(&mut p); if self.src.get(p) != Some(&b'=') { return self.fault(XmlError::MalformedSyntax, p); } p += 1; self.ws(&mut p);
            let Some(&quote @ (b'\'' | b'"')) = self.src.get(p) else { return self.fault(XmlError::MalformedSyntax, p) }; p += 1; let value_start = p;
            while p < self.src.len() && self.src[p] != quote {
                if self.src[p] == b'<' { return self.fault(XmlError::MalformedSyntax, p); }
                if self.src[p] == b'&' { self.reference(&mut p)?; } else { p += 1; }
            }
            if p == self.src.len() { return self.fault(XmlError::MalformedSyntax, value_start - 1); }
            self.emit(XmlToken { kind: TokenKind::Attribute, source: XmlSpan { offset: attr_start, length: p + 1 - attr_start }, name: an, prefix: ap, local_name: al, value: XmlSpan { offset: value_start, length: p - value_start }, depth: self.depth, ..XmlToken::default() }, attr_start)?;
            p += 1; local_attrs += 1; self.attrs += 1; self.result.attribute_count += 1;
        }
    }
    fn open_tag(&mut self) -> Result<(), Fault> { self.tag(false)?; self.result.element_count += 1; Ok(()) }
    fn doctype_end(&self, start: usize) -> Result<usize, Fault> {
        #[derive(Clone, Copy, PartialEq)] enum S { Start, Main, Quote, Sub, SubQuote, Lt, Bang, Dash, Comment, Pi }
        let mut s=S::Start; let mut q=0; let mut run=0; let mut closed=false; let mut i=start+9;
        while i < self.src.len() { let c=self.src[i]; match s {
            S::Start => { if !is_xml_whitespace(c) { return self.fault(XmlError::MalformedSyntax,i) } s=S::Main; },
            S::Main => match c { b'"'|b'\''=>{q=c;s=S::Quote}, b'['=>{if closed{return self.fault(XmlError::MalformedSyntax,i)}s=S::Sub}, b'>'=>return Ok(i+1), b'<'=>return self.fault(XmlError::MalformedSyntax,i), _=>{} },
            S::Quote=>if c==q{s=S::Main}, S::Sub=>match c { b'"'|b'\''=>{q=c;s=S::SubQuote},b'<'=>s=S::Lt,b']'=>{closed=true;s=S::Main},_=>{} },
            S::SubQuote=>if c==q{s=S::Sub}, S::Lt=>match c {b'!'=>s=S::Bang,b'?'=>{run=0;s=S::Pi},_=>s=S::Sub},
            S::Bang=>if c==b'-'{s=S::Dash}else{s=S::Sub}, S::Dash=>if c==b'-'{run=0;s=S::Comment}else{s=S::Sub},
            S::Comment=>if c==b'-'{run=(run+1).min(2)}else if c==b'>'&&run>=2{s=S::Sub}else{run=0},
            S::Pi=>if c==b'>'&&run==1{s=S::Sub}else{run=usize::from(c==b'?')},
        } i+=1; }
        self.fault(XmlError::MalformedSyntax,start)
    }
    fn run(mut self) -> Result<(Vec<XmlToken>, XmlResult), Fault> {
        // Validate every source scalar before parsing, preserving C tokenizer error precedence.
        let mut p=0; while p < self.src.len() { let at=p; let Some((cp,n))=utf8_next(self.src,p) else{return self.fault(XmlError::InvalidUtf8,at)}; if !is_xml_char(cp){return self.fault(XmlError::InvalidCharacter,at)} p=n; }
        if self.starts(0,b"\xef\xbb\xbf") { self.pos=3; }
        let mut doctype=false;
        while self.pos < self.src.len() {
            let start=self.pos;
            if self.src[start] != b'<' {
                let mut p=start; while p<self.src.len() && self.src[p]!=b'<' { if self.starts(p,b"]]>" ) { return self.fault(XmlError::MalformedSyntax,p) } if self.src[p]==b'&' { self.reference(&mut p)?; } else { p+=1; } }
                if p-start > self.limits.text_run_bytes { return self.fault(XmlError::TextLimit,start); }
                let nonspace=self.src[start..p].iter().any(|b| !is_xml_whitespace(*b)); if self.depth==0 && nonspace { let i=self.src[start..p].iter().position(|b| !is_xml_whitespace(*b)).unwrap()+start; return self.fault(XmlError::MalformedSyntax,i); }
                let counted=self.depth!=0||nonspace; if counted { self.node(start)?; }
                self.emit(XmlToken {kind:TokenKind::Text,source:XmlSpan{offset:start,length:p-start},value:XmlSpan{offset:start,length:p-start},depth:self.depth,..XmlToken::default()},start)?; self.pos=p; continue;
            }
            if self.starts(start,b"<!--") { let mut p=start+4; while p+2<self.src.len() && !self.starts(p,b"-->") { if self.starts(p,b"--") { return self.fault(XmlError::MalformedSyntax,p) } p+=1; } if p+2>=self.src.len(){return self.fault(XmlError::MalformedSyntax,start)} self.node(start)?; self.emit(XmlToken{kind:TokenKind::Comment,source:XmlSpan{offset:start,length:p+3-start},value:XmlSpan{offset:start+4,length:p-start-4},depth:self.depth,..XmlToken::default()},start)?;self.pos=p+3;continue; }
            if self.starts(start,b"<![CDATA[") { let mut p=start+9;while p+2<self.src.len()&&!self.starts(p,b"]]>"){p+=1} if p+2>=self.src.len()||self.depth==0{return self.fault(XmlError::MalformedSyntax,start)} if p-(start+9)>self.limits.text_run_bytes{return self.fault(XmlError::TextLimit,start+9)} self.node(start)?;self.emit(XmlToken{kind:TokenKind::Cdata,source:XmlSpan{offset:start,length:p+3-start},value:XmlSpan{offset:start+9,length:p-start-9},depth:self.depth,..XmlToken::default()},start)?;self.pos=p+3;continue; }
            if self.starts(start,b"<!DOCTYPE") { if doctype||self.depth!=0||self.roots!=0{return self.fault(XmlError::MalformedSyntax,start)} let end=self.doctype_end(start)?; self.node(start)?; self.emit(XmlToken{kind:TokenKind::Doctype,source:XmlSpan{offset:start,length:end-start},..XmlToken::default()},start)?;doctype=true;self.pos=end;continue; }
            if self.starts(start,b"<!ENTITY") {return self.fault(XmlError::UnsupportedDtd,start)}
            if self.starts(start,b"<?") { let mut p=start+2; let (name,_,_)=self.name(&mut p,false)?;let declaration=name.slice(self.src)==Some(b"xml");let folded=name.slice(self.src).unwrap_or_default();if !declaration&&folded.eq_ignore_ascii_case(b"xml"){return self.fault(XmlError::MalformedSyntax,start)}if declaration&&start!=0&&!(start==3&&self.starts(0,b"\xef\xbb\xbf")){return self.fault(XmlError::MalformedSyntax,start)} if p>=self.src.len()||(!is_xml_whitespace(self.src[p])&&!self.starts(p,b"?>")){return self.fault(XmlError::MalformedSyntax,p)} if declaration&&self.starts(p,b"?>"){return self.fault(XmlError::MalformedSyntax,p)} while p<self.src.len()&&is_xml_whitespace(self.src[p]){p+=1}let data=p;while p+1<self.src.len()&&!self.starts(p,b"?>"){p+=1}if p+1>=self.src.len(){return self.fault(XmlError::MalformedSyntax,start)} let kind=if declaration{TokenKind::Declaration}else{self.node(start)?;TokenKind::ProcessingInstruction};if declaration{validate_declaration(self.src,XmlSpan{offset:data,length:p-data})?;}self.emit(XmlToken{kind,source:XmlSpan{offset:start,length:p+2-start},name,value:XmlSpan{offset:data,length:p-data},depth:self.depth,..XmlToken::default()},start)?;self.pos=p+2;continue; }
            if self.starts(start,b"</") {self.tag(true)?;continue}
            if self.starts(start,b"<!") {return self.fault(XmlError::MalformedSyntax,start)}
            self.open_tag()?;
        }
        if self.depth!=0||self.roots==0{return self.fault(XmlError::IncompleteDocument,self.src.len())}
        Ok((self.tokens,self.result))
    }
}

pub(crate) fn validate_declaration(src: &[u8], span: XmlSpan) -> Result<(), Fault> {
    let end=span.end().unwrap_or(src.len());let mut p=span.offset;let(mut version,mut encoding,mut standalone)=(false,false,false);
    while p<end { while p<end&&is_xml_whitespace(src[p]){p+=1} if p==end{break} let ns=p;while p<end&&src[p].is_ascii_alphabetic(){p+=1}let key=&src[ns..p];while p<end&&is_xml_whitespace(src[p]){p+=1}if p>=end||src[p]!=b'='{return Err(Fault(XmlError::MalformedSyntax,p))}p+=1;while p<end&&is_xml_whitespace(src[p]){p+=1}if p>=end||!matches!(src[p],b'\''|b'"'){return Err(Fault(XmlError::MalformedSyntax,p))}let q=src[p];p+=1;let vs=p;while p<end&&src[p]!=q{p+=1}if p>=end{return Err(Fault(XmlError::MalformedSyntax,vs-1))}let value=&src[vs..p];p+=1;if p<end&&!is_xml_whitespace(src[p]){return Err(Fault(XmlError::MalformedSyntax,p))}
        match key { b"version" if !version&&!encoding&&!standalone&&value==b"1.0"=>version=true,
            b"encoding" if version&&!encoding&&!standalone&&!value.is_empty()&&value[0].is_ascii_alphabetic()=>{if !value.iter().all(|c|c.is_ascii_alphanumeric()||matches!(c,b'.'|b'_'|b'-')){return Err(Fault(XmlError::MalformedSyntax,vs))}if !value.eq_ignore_ascii_case(b"utf-8"){return Err(Fault(XmlError::UnsupportedEncoding,vs))}encoding=true},
            b"standalone" if version&&!standalone&&matches!(value,b"yes"|b"no")=>standalone=true,
            _=>return Err(Fault(XmlError::MalformedSyntax,ns)) }
    }
    if !version{return Err(Fault(XmlError::MalformedSyntax,span.offset))}Ok(())
}

pub fn tokenize(source: &[u8], mut limits: XmlLimits) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut limits, MAX_INPUT_BYTES, usize::MAX) }
pub fn tokenize_large(source: &[u8]) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut XmlLimits { input_bytes: MAX_LARGE_INPUT_BYTES, ..XmlLimits::default() }, MAX_LARGE_INPUT_BYTES, usize::MAX) }
pub fn tokenize_with_capacity(source: &[u8], limits: XmlLimits, token_capacity: usize) -> (Vec<XmlToken>, XmlResult) { tokenize_impl(source, &mut limits.clone(), MAX_INPUT_BYTES, token_capacity) }
pub fn tokenize_large_with_capacity(source: &[u8], token_capacity: usize) -> (Vec<XmlToken>, XmlResult) {
    tokenize_impl(source, &mut XmlLimits { input_bytes: MAX_LARGE_INPUT_BYTES, ..XmlLimits::default() }, MAX_LARGE_INPUT_BYTES, token_capacity)
}
pub fn tokenize_cancelable<F: FnMut() -> bool>(source: &[u8], limits: XmlLimits, token_capacity: usize, mut canceled: F) -> (Vec<XmlToken>, XmlResult, StreamStatus) {
    if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
    for _chunk in source.chunks(64 * 1024) {
        if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
    }
    let (tokens, result) = tokenize_with_capacity(source, limits, token_capacity);
    if result.diagnostic.category != XmlError::None { return (tokens, result, StreamStatus::Failed); }
    if canceled() { return (Vec::new(), XmlResult::default(), StreamStatus::Canceled); }
    (tokens, result, StreamStatus::Complete)
}
pub fn tokenize_large_cancelable<F: FnMut() -> bool>(source:&[u8],token_capacity:usize,mut canceled:F)->(Vec<XmlToken>,XmlResult,StreamStatus){
    if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}
    for _chunk in source.chunks(64*1024){if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}}
    let (tokens,result)=tokenize_large_with_capacity(source,token_capacity);
    if result.diagnostic.category!=XmlError::None{return (tokens,result,StreamStatus::Failed)}
    if canceled(){return (Vec::new(),XmlResult::default(),StreamStatus::Canceled)}(tokens,result,StreamStatus::Complete)
}
fn tokenize_impl(source:&[u8],limits:&mut XmlLimits,hard:usize,token_capacity:usize)->(Vec<XmlToken>,XmlResult){
    limits.input_bytes=limits.input_bytes.min(hard);limits.nesting_depth=limits.nesting_depth.min(MAX_DEPTH);limits.nodes=limits.nodes.min(MAX_NODES);limits.attributes_per_element=limits.attributes_per_element.min(MAX_ATTRIBUTES_PER_ELEMENT);limits.total_attributes=limits.total_attributes.min(MAX_TOTAL_ATTRIBUTES);limits.text_run_bytes=limits.text_run_bytes.min(MAX_TEXT_RUN_BYTES);
    if source.len()>limits.input_bytes { return (Vec::new(),XmlResult{diagnostic:XmlDiagnostic{category:XmlError::InputLimit,offset:limits.input_bytes},..XmlResult::default()}); }
    let parser=Parser{src:source,pos:0,depth:0,roots:0,attrs:0,limits:*limits,tokens:Vec::new(),result:XmlResult::default(),open_names:Vec::new(),token_capacity};
    match parser.run(){Ok((tokens,result))=>(tokens,result),Err(Fault(category,offset))=>(Vec::new(),XmlResult{diagnostic:XmlDiagnostic{category,offset},..XmlResult::default()})}
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StreamStatus { Ok, Complete, Failed, Canceled }

pub fn visit_tokens<F:FnMut(&XmlToken)->bool>(source:&[u8],limits:XmlLimits,visitor:&mut F)->StreamStatus{
    let (tokens,result)=tokenize(source,limits);if result.diagnostic.category!=XmlError::None{return StreamStatus::Failed}
    for token in &tokens {if !visitor(token){return StreamStatus::Canceled}}StreamStatus::Complete
}

pub fn decode_attribute_value(source:&[u8],raw:XmlSpan,output:&mut [u8])->Result<usize,usize>{
    let bytes=raw.slice(source).ok_or(0usize)?;let mut p=0;let mut out=0;
    while p<bytes.len(){let at=p;if bytes[p]!=b'&'{let Some((cp,end))=utf8_next(bytes,p)else{return Err(at)};if !is_xml_char(cp)||end-p>output.len().saturating_sub(out){return Err(at)}output[out..out+end-p].copy_from_slice(&bytes[p..end]);out+=end-p;p=end;continue}
        let semi=bytes[p+1..].iter().take(16).position(|b|*b==b';').map(|v|p+1+v).ok_or(at)?;let body=&bytes[p+1..semi];let cp=match body{b"amp"=>38,b"lt"=>60,b"gt"=>62,b"quot"=>34,b"apos"=>39,_ if body.starts_with(b"#")=>{let (digits,radix)=if body.get(1)==Some(&b'x'){(&body[2..],16)}else{(&body[1..],10)};if digits.is_empty(){return Err(at)}let mut n=0u32;for c in digits{let d=match c{b'0'..=b'9'=>(c-b'0')as u32,b'a'..=b'f'=>(c-b'a'+10)as u32,b'A'..=b'F'=>(c-b'A'+10)as u32,_=>return Err(at)};n=n.checked_mul(radix).and_then(|v|v.checked_add(d)).ok_or(at)?}n},_=>return Err(at)};if !is_xml_char(cp){return Err(at)}let ch=char::from_u32(cp).ok_or(at)?;let mut tmp=[0;4];let enc=ch.encode_utf8(&mut tmp).as_bytes();if enc.len()>output.len().saturating_sub(out){return Err(at)}output[out..out+enc.len()].copy_from_slice(enc);out+=enc.len();p=semi+1;
    }Ok(out)
}

use crate::{is_name_char, is_name_start, is_xml_char, is_xml_whitespace, utf8_next};
use crate::tokenizer::{validate_declaration, MAX_ATTRIBUTES_PER_ELEMENT, MAX_DEPTH, MAX_LARGE_INPUT_BYTES,
    MAX_NODES, MAX_TOKEN_NAME_BYTES};
use crate::{StreamStatus, TokenKind, XmlDiagnostic, XmlError, XmlLimits, XmlResult, XmlSpan, XmlToken};
use core::mem::size_of;

const STEP_CAP: usize = 64 * 1024;

#[derive(Clone, Copy)]
struct NameScan { start: usize, pos: usize, first_colon: Option<usize> }
#[derive(Clone, Copy)]
enum RefMode { Start, Numeric { hex: bool, digits: usize, value: u32 }, Named(NameScan) }
#[derive(Clone, Copy)]
struct RefScan { start: usize, pos: usize, mode: RefMode }
#[derive(Clone, Copy, Default)]
struct NameParts { name: XmlSpan, prefix: XmlSpan, local: XmlSpan }

#[derive(Clone, Copy, PartialEq, Eq)]
enum DtdPhase { Start, Main, Quote, Subset, SubsetQuote, Lt, Bang, BangDash, Comment, Pi }
#[derive(Clone, Copy)]
struct Dtd { phase: DtdPhase, quote: u8, run: u8, subset_closed: bool }
impl Default for Dtd { fn default() -> Self { Self { phase: DtdPhase::Start, quote: 0, run: 0, subset_closed: false } } }
impl Dtd {
    fn step(&mut self, c: u8) -> Result<bool, ()> {
        loop { match self.phase {
            DtdPhase::Start => { if !is_xml_whitespace(c) { return Err(()) } self.phase=DtdPhase::Main; return Ok(false) },
            DtdPhase::Main => match c { b'"'|b'\''=>{self.quote=c;self.phase=DtdPhase::Quote},b'['=>{if self.subset_closed{return Err(())}self.phase=DtdPhase::Subset},b'>'=>return Ok(true),b'<'=>return Err(()),_=>{} },
            DtdPhase::Quote=>if c==self.quote{self.phase=DtdPhase::Main},
            DtdPhase::Subset=>match c {b'"'|b'\''=>{self.quote=c;self.phase=DtdPhase::SubsetQuote},b'<'=>self.phase=DtdPhase::Lt,b']'=>{self.subset_closed=true;self.phase=DtdPhase::Main},_=>{}},
            DtdPhase::SubsetQuote=>if c==self.quote{self.phase=DtdPhase::Subset},
            DtdPhase::Lt=>match c{b'!'=>{self.phase=DtdPhase::Bang;return Ok(false)},b'?'=>{self.run=0;self.phase=DtdPhase::Pi;return Ok(false)},_=>{self.phase=DtdPhase::Subset;continue}},
            DtdPhase::Bang=>if c==b'-'{self.phase=DtdPhase::BangDash;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},
            DtdPhase::BangDash=>if c==b'-'{self.run=0;self.phase=DtdPhase::Comment;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},
            DtdPhase::Comment=>if c==b'-'{self.run=(self.run+1).min(2)}else if c==b'>'&&self.run>=2{self.phase=DtdPhase::Subset}else{self.run=0},
            DtdPhase::Pi=>if c==b'>'&&self.run==1{self.phase=DtdPhase::Subset}else{self.run=u8::from(c==b'?')},
        } return Ok(false) }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum TagPhase { Prefix, Name, Between, AttrName, AttrEq, AttrQuote, AttrValue, EndBetween }
struct TagState { start:usize, pos:usize, closing:bool, phase:TagPhase, name_scan:Option<NameScan>, name:Option<NameParts>,
    attr_scan:Option<NameScan>, attr:Option<NameParts>, attr_start:usize, value_start:usize, quote:u8,
    local_attrs:usize, separated:bool, token_index:usize, reference:Option<RefScan> }
impl TagState { fn new(start:usize,closing:bool)->Self {Self{start,pos:start,closing,phase:TagPhase::Prefix,name_scan:None,name:None,attr_scan:None,attr:None,attr_start:0,value_start:0,quote:0,local_attrs:0,separated:false,token_index:0,reference:None}} }

enum Pending {
    None,
    Text { start:usize, pos:usize, nonspace:bool, first_nonspace:usize, reference:Option<RefScan> },
    Comment { start:usize, pos:usize, dashes:u8 },
    Cdata { start:usize, pos:usize, brackets:u8 },
    Doctype { start:usize, pos:usize, state:Dtd },
    Pi { start:usize, pos:usize, name_scan:Option<NameScan>, name:Option<XmlSpan>, declaration:bool, data:Option<usize>, separating:bool, question:bool },
}

pub struct XmlTokenStream<'a> {
    source:&'a [u8], limits:XmlLimits, result:XmlResult, tokens:Vec<XmlToken>,
    tag_scratch:Vec<XmlToken>, storage_limit:usize, visitor_mode:bool,
    cursor:usize, parse_limit:usize, char_cursor:usize,
    chars_complete:bool, depth:usize, roots:usize, total_attrs:usize, open_names:Vec<XmlSpan>,
    pending:Pending, tag:Option<TagState>, doctype_seen:bool, complete:bool, canceled:bool, taken:bool,
}

impl<'a> XmlTokenStream<'a> {
    pub fn new(source:&'a [u8],max_storage_bytes:usize)->Result<Self,StreamStatus>{
        Self::construct(source,max_storage_bytes,false)
    }
    pub fn new_visitor(source:&'a [u8])->Result<Self,StreamStatus>{
        let scratch=MAX_ATTRIBUTES_PER_ELEMENT.checked_add(1).and_then(|n|n.checked_mul(size_of::<XmlToken>())).ok_or(StreamStatus::Failed)?;
        Self::construct(source,scratch,true)
    }
    fn construct(source:&'a [u8],max_storage_bytes:usize,visitor_mode:bool)->Result<Self,StreamStatus>{
        if source.len()>MAX_LARGE_INPUT_BYTES||(!visitor_mode&&max_storage_bytes<size_of::<XmlToken>()){return Err(StreamStatus::Failed)}
        let limits=XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()};
        let mut tag_scratch=Vec::new();
        if visitor_mode&&tag_scratch.try_reserve_exact(MAX_ATTRIBUTES_PER_ELEMENT+1).is_err(){return Err(StreamStatus::Failed)}
        let mut open_names=Vec::new();if open_names.try_reserve_exact(MAX_DEPTH).is_err(){return Err(StreamStatus::Failed)}
        let cursor=if source.starts_with(b"\xef\xbb\xbf"){3}else{0};
        Ok(Self{source,limits,result:XmlResult::default(),tokens:Vec::new(),tag_scratch,storage_limit:max_storage_bytes,visitor_mode,
            cursor,parse_limit:cursor,char_cursor:0,chars_complete:false,depth:0,roots:0,total_attrs:0,open_names,
            pending:Pending::None,tag:None,doctype_seen:false,complete:false,canceled:false,taken:false})
    }

    pub fn step(&mut self,budget:usize,canceled:bool)->StreamStatus{
        let mut poll=||canceled;
        self.step_inner(budget,&mut poll,None)
    }
    pub fn step_with_visitor<F:FnMut(&XmlToken)->bool>(&mut self,budget:usize,canceled:bool,visitor:&mut F)->StreamStatus{
        let mut poll=||canceled;
        self.step_inner(budget,&mut poll,Some(visitor))
    }
    pub fn step_with_visitor_and_cancel<F:FnMut(&XmlToken)->bool,C:FnMut()->bool>(&mut self,budget:usize,visitor:&mut F,cancel:&mut C)->StreamStatus{
        self.step_inner(budget,cancel,Some(visitor))
    }
    pub fn step_with_cancel<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->StreamStatus{
        self.step_inner(budget,cancel,None)
    }
    fn step_inner<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C,mut visitor:Option<&mut dyn FnMut(&XmlToken)->bool>)->StreamStatus{
        if self.canceled{return StreamStatus::Canceled} if self.result.diagnostic.category!=XmlError::None{return StreamStatus::Failed}
        if budget==0{return StreamStatus::Failed} if self.complete{return StreamStatus::Complete}
        if self.visitor_mode&&visitor.is_none(){return StreamStatus::Failed}
        if cancel(){self.canceled=true;return StreamStatus::Canceled}
        let budget=budget.min(STEP_CAP);let char_initial=self.char_cursor;
        if !self.scan_chars(budget,cancel){return self.failed_or_canceled()}
        if !self.chars_complete{return StreamStatus::Ok}
        let char_work=self.char_cursor.saturating_sub(char_initial);if char_work>=budget{return StreamStatus::Ok}
        let parse_budget=budget-char_work;let initial=self.frontier();
        let limit=initial.saturating_add(parse_budget).min(self.source.len());self.parse_limit=limit;
        while self.cursor<self.source.len()&&self.frontier().saturating_sub(initial)<parse_budget {
            if cancel(){self.canceled=true;return StreamStatus::Canceled}
            let before=self.frontier();
            if !self.parse_next(limit,&mut visitor,cancel){return self.failed_or_canceled()}
            if self.frontier()==before{break}
        }
        if self.cursor==self.source.len()&&matches!(self.pending,Pending::None)&&self.tag.is_none(){
            if self.depth!=0||self.roots==0{self.fail(XmlError::IncompleteDocument,self.source.len());return self.failed_or_canceled()}
            self.complete=true;
        }
        if self.complete{StreamStatus::Complete}else{StreamStatus::Ok}
    }
    fn scan_chars<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->bool{
        let end=self.char_cursor.saturating_add(budget).min(self.source.len());
        while self.char_cursor<end{
            if cancel(){self.canceled=true;return false}
            let at=self.char_cursor;let lead=self.source[at];
            let width=match lead{0x00..=0x7f=>1,0xc2..=0xdf=>2,0xe0..=0xef=>3,0xf0..=0xf4=>4,_=>1};
            if at.saturating_add(width)>end&&end<self.source.len(){break}
            let Some((cp,next))=utf8_next(self.source,at)else{self.fail(XmlError::InvalidUtf8,at);return false};
            if next>end&&end<self.source.len(){break}
            if !is_xml_char(cp){self.fail(XmlError::InvalidCharacter,at);return false}
            self.char_cursor=next;
        }
        if self.char_cursor==self.source.len(){self.chars_complete=true}
        true
    }
    fn parse_next<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
        if self.tag.is_some(){return self.parse_tag(limit,visitor,cancel)}
        if !matches!(self.pending,Pending::None){return self.parse_pending(limit,visitor,cancel)}
        let p=self.cursor;if p>=limit{return true}
        if self.source[p]!=b'<'{self.pending=Pending::Text{start:p,pos:p,nonspace:false,first_nonspace:0,reference:None};return self.parse_pending(limit,visitor,cancel)}
        if self.source.get(p..p.saturating_add(4))==Some(b"<!--"){self.pending=Pending::Comment{start:p,pos:p+4,dashes:0};return self.parse_pending(limit,visitor,cancel)}
        if self.source.get(p..p.saturating_add(9))==Some(b"<![CDATA["){self.pending=Pending::Cdata{start:p,pos:p+9,brackets:0};return self.parse_pending(limit,visitor,cancel)}
        if self.source.get(p..p.saturating_add(9))==Some(b"<!DOCTYPE"){
            if self.depth!=0||self.roots!=0||self.doctype_seen{self.fail(XmlError::MalformedSyntax,p);return false}
            self.pending=Pending::Doctype{start:p,pos:p+9,state:Dtd::default()};return self.parse_pending(limit,visitor,cancel)
        }
        if self.source.get(p..p.saturating_add(8))==Some(b"<!ENTITY"){self.fail(XmlError::UnsupportedDtd,p);return false}
        if self.source.get(p..p.saturating_add(2))==Some(b"<?"){self.pending=Pending::Pi{start:p,pos:p+2,name_scan:None,name:None,declaration:false,data:None,separating:false,question:false};return self.parse_pending(limit,visitor,cancel)}
        if self.source.get(p..p.saturating_add(2))==Some(b"</"){self.tag=Some(TagState::new(p,true));return self.parse_tag(limit,visitor,cancel)}
        if self.source.get(p..p.saturating_add(2))==Some(b"<!"){self.fail(XmlError::MalformedSyntax,p);return false}
        self.tag=Some(TagState::new(p,false));self.parse_tag(limit,visitor,cancel)
    }
    fn parse_pending<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
        let pending=core::mem::replace(&mut self.pending,Pending::None);
        match pending{
            Pending::None=>true,
            Pending::Text{start,mut pos,mut nonspace,mut first_nonspace,mut reference}=>{
                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};self.canceled=true;return false}
                    if self.source[pos]==b'<'{break}
                    if self.source.get(pos..pos+3)==Some(b"]]>"){self.fail(XmlError::MalformedSyntax,pos);return false}
                    if self.source[pos]==b'&'{let scan=reference.get_or_insert_with(||RefScan::new(pos));match reference_step(self.source,scan,limit){Ok(Some(end))=>{pos=end;reference=None},Ok(None)=>break,Err((e,at))=>{self.fail(e,at);return false}}}
                    else{if !is_xml_whitespace(self.source[pos])&&!nonspace{nonspace=true;first_nonspace=pos}pos+=1}
                }
                if pos<self.source.len()&&self.source[pos]==b'<'{return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
                if pos==self.source.len(){return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
                self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};true
            }
            Pending::Comment{start,mut pos,mut dashes}=>{
                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Comment{start,pos,dashes};self.canceled=true;return false}
                    let c=self.source[pos];if dashes==2{if c!=b'>'{self.fail(XmlError::MalformedSyntax,pos-2);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Comment,source:span(start,end),value:span(start+4,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}
                    dashes=if c==b'-'{dashes+1}else{0};pos+=1;
                }
                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Comment{start,pos,dashes};true
            }
            Pending::Cdata{start,mut pos,mut brackets}=>{
                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Cdata{start,pos,brackets};self.canceled=true;return false}
                    let c=self.source[pos];if c==b'>'&&brackets>=2{if self.depth==0{self.fail(XmlError::MalformedSyntax,start);return false}
                        if pos-2-(start+9)>self.limits.text_run_bytes{self.fail(XmlError::TextLimit,start+9);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Cdata,source:span(start,end),value:span(start+9,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}brackets=if c==b']'{(brackets+1).min(2)}else{0};pos+=1;
                }
                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Cdata{start,pos,brackets};true
            }
            Pending::Doctype{start,mut pos,mut state}=>{
                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Doctype{start,pos,state};self.canceled=true;return false}
                    match state.step(self.source[pos]){Ok(done)=>{pos+=1;if done{let t=XmlToken{kind:TokenKind::Doctype,source:span(start,pos),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}self.doctype_seen=true;if !self.emit(t,start,visitor){return false}self.cursor=pos;return true}},Err(())=>{self.fail(XmlError::MalformedSyntax,pos);return false}}
                }
                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Doctype{start,pos,state};true
            }
            Pending::Pi{start,mut pos,mut name_scan,mut name,mut declaration,mut data,mut separating,mut question}=>{
                if name.is_none(){let scan=name_scan.get_or_insert(NameScan{start:pos,pos,first_colon:None});match scan_name(self.source,scan,limit,false){Ok(Some(parts))=>{name=Some(parts.name);pos=scan.pos;declaration=parts.name.slice(self.source)==Some(b"xml");let raw=parts.name.slice(self.source).unwrap_or_default();if !declaration&&raw.len()==3&&raw.eq_ignore_ascii_case(b"xml"){self.fail(XmlError::MalformedSyntax,start);return false}if declaration&&start!=0&&!(start==3&&self.source.starts_with(b"\xef\xbb\xbf")){self.fail(XmlError::MalformedSyntax,start);return false}},Ok(None)=>{if pos==self.source.len(){self.fail(XmlError::InvalidName,pos);return false}self.pending=Pending::Pi{start,pos:scan.pos,name_scan,name,declaration,data,separating,question};return true},Err((e,at))=>{self.fail(e,at);return false}}}
                if data.is_none(){if pos>=limit{if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true}
                    if !separating&&self.source.get(pos..pos.saturating_add(2))==Some(b"?>"){if declaration{self.fail(XmlError::MalformedSyntax,pos);return false}data=Some(pos)}
                    else if !separating&&!is_xml_whitespace(self.source[pos]){self.fail(XmlError::MalformedSyntax,pos);return false}
                    else{separating=true;while pos<limit&&pos<self.source.len()&&is_xml_whitespace(self.source[pos]){pos+=1}if pos==limit&&pos<self.source.len(){self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true}data=Some(pos)}
                }
                let begin=data.unwrap_or(pos);if data.is_none(){pos=begin}
                let mut end=None;while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};self.canceled=true;return false}let c=self.source[pos];if c==b'>'&&question{end=Some(pos+1);break}question=c==b'?';pos+=1}
                let Some(end)=end else{if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true};
                let end_start=end-2;let n=name.unwrap_or_default();let t=XmlToken{kind:if declaration{TokenKind::Declaration}else{TokenKind::ProcessingInstruction},source:span(start,end),name:n,value:span(begin,end_start),depth:self.depth,..XmlToken::default()};
                if declaration{if let Err(crate::tokenizer::Fault(e,at))=validate_declaration(self.source,t.value){self.fail(e,at);return false}}else if !self.count_node(start){return false}
                if !self.emit(t,start,visitor){return false}self.cursor=end;true
            }
        }
    }
    fn finish_text(&mut self,start:usize,end:usize,nonspace:bool,first:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>)->bool{
        if end-start>self.limits.text_run_bytes{self.fail(XmlError::TextLimit,start);return false}
        if self.depth==0&&nonspace{self.fail(XmlError::MalformedSyntax,first);return false}
        if (self.depth!=0||nonspace)&&!self.count_node(start){return false}let source=span(start,end);let t=XmlToken{kind:TokenKind::Text,source,value:source,depth:self.depth,..XmlToken::default()};
        if !self.emit(t,start,visitor){return false}self.cursor=end;true
    }

    fn parse_tag<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
        let Some(mut t)=self.tag.take()else{return true};
        while t.pos<limit&&t.pos<self.source.len(){if cancel(){self.tag=Some(t);self.canceled=true;return false}
            match t.phase{
                TagPhase::Prefix=>{let expected=if t.closing{if t.pos==t.start{b'<' }else{b'/'} }else{b'<'};if self.source[t.pos]!=expected{self.fail(XmlError::MalformedSyntax,t.pos);return false}t.pos+=1;if (t.closing&&t.pos==t.start+2)||(!t.closing&&t.pos==t.start+1){t.phase=TagPhase::Name;t.name_scan=Some(NameScan{start:t.pos,pos:t.pos,first_colon:None});}},
                TagPhase::Name=>{let qname=true;let Some(scan)=t.name_scan.as_mut()else{self.fail(XmlError::InvalidName,t.pos);return false};match scan_name(self.source,scan,limit,qname){Ok(Some(parts))=>{t.pos=scan.pos;t.name=Some(parts);if t.closing{let n=parts.name;if self.depth==0||self.open_names.last().and_then(|s|s.slice(self.source))!=n.slice(self.source){self.fail(XmlError::MismatchedTag,t.start);return false}t.phase=TagPhase::EndBetween}else{
                    if self.depth==0{if self.roots!=0{self.fail(XmlError::MultipleRoots,t.start);return false}self.roots+=1}
                    if self.depth>=self.limits.nesting_depth||self.depth>=MAX_DEPTH{self.fail(XmlError::DepthLimit,t.start);return false}if !self.count_node(t.start){return false}
                    let tok=XmlToken{kind:TokenKind::StartElement,source:span(t.start,t.pos),name:parts.name,prefix:parts.prefix,local_name:parts.local,depth:self.depth,..XmlToken::default()};
                    t.token_index=self.tag_len();if !self.stage_tag(tok,t.start){return false}t.local_attrs=0;t.phase=TagPhase::Between;t.separated=false;}}
                    Ok(None)=>{self.tag=Some(t);return true},Err((e,at))=>{self.fail(e,at);return false}}},
                TagPhase::Between=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1;t.separated=true}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}
                    if t.pos>=self.source.len(){self.fail(XmlError::MalformedSyntax,t.start);return false}
                    if self.source[t.pos]==b'>'{let end=t.pos+1;if !self.finish_start(&mut t,end,false,visitor){return false}return true}
