fn span(start:usize,end:usize)->XmlSpan{XmlSpan{offset:start,length:end.saturating_sub(start)}}
fn scan_name(source:&[u8],scan:&mut NameScan,limit:usize,qname:bool)->Result<Option<NameParts>,(XmlError,usize)>{
