//! Bounded XML 1.0 byte-preserving tokenizer and resumable tag reader.

use vexel_base::Span;

pub const MAX_READER_SOURCE_BYTES: usize = 1024 * 1024 * 1024;
pub const MAX_READER_STEP_BYTES: usize = 64 * 1024;
pub const MAX_READER_NAME_BYTES: usize = 4096;

mod tokenizer;
pub use tokenizer::*;
mod stream;
pub use stream::XmlTokenStream;

/// XML 1.0 Fifth Edition `Char` production.
pub const fn is_xml_char(cp: u32) -> bool {
    cp == 0x9
        || cp == 0xa
        || cp == 0xd
        || (cp >= 0x20 && cp <= 0xd7ff)
        || (cp >= 0xe000 && cp <= 0xfffd)
        || (cp >= 0x10000 && cp <= 0x10ffff)
}

/// Decodes one strict UTF-8 scalar at `position` and returns it with the next
/// byte offset. On failure, callers retain their original position.
pub fn utf8_next(bytes: &[u8], position: usize) -> Option<(u32, usize)> {
    let first = *bytes.get(position)?;
    let (count, mut value) = match first {
        0x00..=0x7f => (1usize, u32::from(first)),
        0xc2..=0xdf => (2, u32::from(first & 0x1f)),
        0xe0..=0xef => (3, u32::from(first & 0x0f)),
        0xf0..=0xf4 => (4, u32::from(first & 0x07)),
        _ => return None,
    };
    let end = position.checked_add(count)?;
    let tail = bytes.get(position + 1..end)?;
    for &byte in tail {
        if byte & 0xc0 != 0x80 {
            return None;
        }
        value = (value << 6) | u32::from(byte & 0x3f);
    }
    let second = *tail.first().unwrap_or(&0);
    if (count == 3 && ((first == 0xe0 && second < 0xa0) || (first == 0xed && second >= 0xa0)))
        || (count == 4 && ((first == 0xf0 && second < 0x90) || (first == 0xf4 && second >= 0x90)))
        || value > 0x10ffff
        || (0xd800..=0xdfff).contains(&value)
    {
        return None;
    }
    Some((value, end))
}

/// XML 1.0 Fifth Edition `NameStartChar` production.
pub const fn is_name_start(cp: u32) -> bool {
    cp == 0x3a
        || cp == 0x5f
        || (cp >= 0x41 && cp <= 0x5a)
        || (cp >= 0x61 && cp <= 0x7a)
        || (cp >= 0xc0 && cp <= 0xd6)
        || (cp >= 0xd8 && cp <= 0xf6)
        || (cp >= 0xf8 && cp <= 0x2ff)
        || (cp >= 0x370 && cp <= 0x37d)
        || (cp >= 0x37f && cp <= 0x1fff)
        || (cp >= 0x200c && cp <= 0x200d)
        || (cp >= 0x2070 && cp <= 0x218f)
        || (cp >= 0x2c00 && cp <= 0x2fef)
        || (cp >= 0x3001 && cp <= 0xd7ff)
        || (cp >= 0xf900 && cp <= 0xfdcf)
    let length = decode_attribute_value(raw, XmlSpan { offset: 0, length: raw.len() }, &mut out).unwrap();
    assert_eq!(&out[..length], "a&A😀z".as_bytes());
    for bad in [&b"&unknown;"[..], &b"&#;"[..], &b"&#x;"[..], &b"&#1114112;"[..], &b"&amp"[..]] {
        assert_eq!(decode_attribute_value(bad, XmlSpan { offset: 0, length: bad.len() }, &mut out), Err(0));
    }
}

#[test]
fn token_stream_is_resumable_cancellable_and_storage_bounded() {
    let source = b"<a><b/></a>";
    let mut stream = XmlTokenStream::new(source, 32 * core::mem::size_of::<XmlToken>()).unwrap();
    loop {
        let before = stream.bytes_read();
        match stream.step(2, false) {
            StreamStatus::Ok => {},
            StreamStatus::Complete => break,
            status => panic!("unexpected stream status: {status:?}"),
        }
        assert!(stream.bytes_read().saturating_sub(before) <= 2);
    }
    assert_eq!(stream.result().element_count, 2);
    assert_eq!(stream.take().unwrap().len(), 3);
    let mut canceled = XmlTokenStream::new(source, 64 * core::mem::size_of::<XmlToken>()).unwrap();
    assert_eq!(canceled.step(1, true), StreamStatus::Canceled);
    let mut too_small = XmlTokenStream::new(source, core::mem::size_of::<XmlToken>()).unwrap();
    assert_eq!(too_small.step(usize::MAX, false), StreamStatus::Failed);
    assert_eq!(too_small.result().diagnostic.category, XmlError::OutputExhausted);

    let mut seen = Vec::new();
    let mut visitor_stream = XmlTokenStream::new_visitor(source).unwrap();
    loop {
        let status = visitor_stream.step_with_visitor(3, false, &mut |token| { seen.push(token.kind); true });
        assert!(visitor_stream.visitor_storage_bytes() <= (MAX_ATTRIBUTES_PER_ELEMENT + 1) * core::mem::size_of::<XmlToken>());
        if status == StreamStatus::Complete { break; }
        assert_eq!(status, StreamStatus::Ok);
    }
    assert_eq!(seen, [TokenKind::StartElement, TokenKind::EmptyElement, TokenKind::EndElement]);
    let entity_source = b"<r>&#123456;&amp;</r>";
    let mut entity_stream = XmlTokenStream::new_visitor(entity_source).unwrap();
    let mut entity_tokens = Vec::new();
    let mut entity_steps = 0;
    loop {
        let before = entity_stream.bytes_read();
        let status = entity_stream.step_with_visitor(1, false, &mut |token| { entity_tokens.push(token.kind); true });
        assert!(entity_stream.bytes_read().saturating_sub(before) <= 1);
        entity_steps += 1;
        assert!(entity_steps <= entity_source.len() * 4, "steps={entity_steps}, bytes={}, status={status:?}", entity_stream.bytes_read());
        if status == StreamStatus::Complete { break; }
        assert_eq!(status, StreamStatus::Ok, "diagnostic={:?}, bytes={}", entity_stream.result().diagnostic, entity_stream.bytes_read());
    }
    assert_eq!(entity_tokens, [TokenKind::StartElement, TokenKind::Text, TokenKind::EndElement]);
    let marker_source = b"<r><!--c--><?p x?><![CDATA[y]]></r>";
    let mut marker_stream = XmlTokenStream::new_visitor(marker_source).unwrap();
    let mut marker_tokens = Vec::new();
    loop {
        let before = marker_stream.bytes_read();
        let status = marker_stream.step_with_visitor(1, false, &mut |token| { marker_tokens.push(token.kind); true });
        assert!(marker_stream.bytes_read().saturating_sub(before) <= 1);
        if status == StreamStatus::Complete { break; }
        assert_eq!(status, StreamStatus::Ok, "diagnostic={:?}", marker_stream.result().diagnostic);
    }
    assert_eq!(marker_tokens, [TokenKind::StartElement, TokenKind::Comment, TokenKind::ProcessingInstruction, TokenKind::Cdata, TokenKind::EndElement]);
    let mut stopped = XmlTokenStream::new_visitor(source).unwrap();
    loop {
        let status = stopped.step_with_visitor(64, false, &mut |_| false);
        if status == StreamStatus::Canceled { break; }
        assert_eq!(status, StreamStatus::Ok);
    }
    assert_eq!(stopped.step(64, false), StreamStatus::Canceled);

    let mut many = b"<r>".to_vec();
    for _ in 0..2_000 { many.extend_from_slice(b"<a/>"); }
    many.extend_from_slice(b"</r>");
    let mut visitor = XmlTokenStream::new_visitor(&many).unwrap();
    let mut delivered=0usize;
    loop {
        let status=visitor.step_with_visitor(4096,false,&mut |_|{delivered+=1;true});
        assert!(visitor.visitor_storage_bytes() <= (MAX_ATTRIBUTES_PER_ELEMENT+1)*core::mem::size_of::<XmlToken>());
        if status==StreamStatus::Complete{break}assert_eq!(status,StreamStatus::Ok);
    }
    assert_eq!(delivered,2_002);

    let mut large=b"<r>".to_vec();large.extend(std::iter::repeat_n(b'x',256*1024));large.extend_from_slice(b"</r>");
    let mut parsing=XmlTokenStream::new_visitor(&large).unwrap();let mut checks=0usize;
    let mut keep=|_:&XmlToken|true;
    let mut cancel=||{checks+=1;checks>large.len()+128};
    let mut status=StreamStatus::Ok;
    while status==StreamStatus::Ok{status=parsing.step_with_visitor_and_cancel(64*1024,&mut keep,&mut cancel)}
    assert_eq!(status,StreamStatus::Canceled);
    assert!(parsing.bytes_read()>3);
    assert!(parsing.bytes_read()<large.len());
}

#[test]
fn tokenizer_covers_output_callbacks_input_limits_and_error_names() {
    assert_eq!(XmlError::UnsupportedDtd.as_str(), "unsupported_dtd");
    let mut limits = XmlLimits::default(); limits.input_bytes = 2;
    let (_, limited) = tokenize(b"<a/>", limits);
    assert_eq!(limited.diagnostic, XmlDiagnostic { category: XmlError::InputLimit, offset: 2 });
    let (_, _, status) = tokenize_cancelable(b"<a/>", XmlLimits::default(), 8, || true);
    assert_eq!(status, StreamStatus::Canceled);
    let (_, _, status) = tokenize_large_cancelable(b"<a/>", 8, || true);
    assert_eq!(status, StreamStatus::Canceled);
    let large = vec![b'x'; 128 * 1024];
    let mut cancellation_checks = 0;
    let (_, _, status) = tokenize_cancelable(&large, XmlLimits::default(), 8, || {
        cancellation_checks += 1;
        cancellation_checks == 3
    });
    assert_eq!(status, StreamStatus::Canceled);
    assert_eq!(cancellation_checks, 3);
    let mut visited = 0;
    assert_eq!(visit_tokens(b"<a/>", XmlLimits::default(), &mut |_| { visited += 1; false }), StreamStatus::Canceled);
    assert_eq!(visited, 1);

    let raw = b"&#x1f600;";
    let mut tiny = [0; 3];
    assert_eq!(decode_attribute_value(raw, XmlSpan { offset: 0, length: raw.len() }, &mut tiny), Err(0));
    let malformed = [b'<', b'a', b'>', 0xc0, 0xaf, b'<', b'/', b'a', b'>'];
    let (_, invalid) = tokenize(&malformed, XmlLimits::default());
    assert_eq!(invalid.diagnostic, XmlDiagnostic { category: XmlError::InvalidUtf8, offset: 3 });
}
